def _signed_u32(value: int) -> int:
    """Interpret an x86 32-bit immediate as a signed displacement."""
    value &= 0xFFFF_FFFF
    return value - 0x1_0000_0000 if value & 0x8000_0000 else value


def _bounded_plain_unsigned_format_length(
    format_bytes: bytes,
) -> tuple[int, int] | None:
    """Bound a deliberately tiny constant ``printf`` format grammar.

    Literal bytes and ``%%`` emit exactly one byte.  A plain ``%u`` emits
    one through ten decimal digits for a 32-bit argument.  Width, precision,
    length, positional, and every other conversion remain fail-closed.
    """
    if not format_bytes or len(format_bytes) > 256 or b"\0" in format_bytes:
        return None
    minimum = 0
    maximum = 0
    conversions = 0
    cursor = 0
    while cursor < len(format_bytes):
        if format_bytes[cursor] != ord("%"):
            minimum += 1
            maximum += 1
            cursor += 1
            continue
        if cursor + 1 >= len(format_bytes):
            return None
        conversion = format_bytes[cursor + 1]
        if conversion == ord("%"):
            minimum += 1
            maximum += 1
        elif conversion == ord("u"):
            minimum += 1
            maximum += 10
            conversions += 1
        else:
            return None
        cursor += 2
    if conversions == 0 or maximum > 0x1000:
        return None
    return minimum, maximum


def _build_span_overlap_index(
    spans: Iterable[tuple[int, int]],
) -> tuple[tuple[int, ...], tuple[int, ...]]:
    """Index half-open spans by start and the maximum prior end."""
    ordered = sorted(spans)
    starts: list[int] = []
    prefix_max_ends: list[int] = []
    maximum_end: int | None = None
    for start, end in ordered:
        starts.append(start)
        maximum_end = (
            end if maximum_end is None else max(maximum_end, end)
        )
        prefix_max_ends.append(maximum_end)
    return tuple(starts), tuple(prefix_max_ends)


def _span_overlap_index_contains(
    index: tuple[tuple[int, ...], tuple[int, ...]],
    start: int,
    end: int,
) -> bool:
    """Return whether [start, end) overlaps any indexed half-open span."""
    if start >= end:
        return False
    starts, prefix_max_ends = index
    candidate_count = bisect_left(starts, end)
    return (
        candidate_count > 0
        and prefix_max_ends[candidate_count - 1] > start
    )


class CfgRecoveryError(ValueError):
    """Raised when evidence cannot safely seed x86 CFG recovery."""


class ProducerCertificateError(CfgRecoveryError):
    """Raised when a persisted producer certificate is not trustworthy."""


class ProducerCheckpointIncomplete(CfgRecoveryError):
    """Raised after bounded producer work is durably checkpointed."""

    def __init__(
        self,
        *,
        completed_this_run: int,
        discovered_queries: int,
        validated_queries: int,
        pending_queries: int,
        checkpoint_dir: Path,
    ) -> None:
        self.completed_this_run = completed_this_run
        self.discovered_queries = discovered_queries
        self.validated_queries = validated_queries
        self.pending_queries = pending_queries
        self.checkpoint_dir = checkpoint_dir
        super().__init__(
            "producer checkpoint incomplete: "
            f"completed_this_run={completed_this_run};"
            f"discovered={discovered_queries};"
            f"validated={validated_queries};pending={pending_queries};"
            f"checkpoint_dir={checkpoint_dir}"
        )


class _Task4ProofLimit(RuntimeError):
    """Private fail-closed sentinel for the Task 4 relational proof."""

    def __init__(
        self,
        phase: str,
        counter: str,
        observed: int,
        configured: int,
    ) -> None:
        self.phase = phase
        self.counter = counter
        self.observed = observed
        self.configured = configured
        super().__init__(
            f"Task 4 {phase} {counter} cap: "
            f"configured={configured}, observed={observed}"
        )


class _Task4ProofBudget:
    """Phase-labelled finite budget spanning all Task 4 construction."""

    def __init__(self) -> None:
        self.counts: dict[tuple[str, str], int] = defaultdict(int)

    def _tick(
        self,
        phase: str,
        counter: str,
        limit: int,
    ) -> None:
        key = (phase, counter)
        observed = self.counts[key] + 1
        self.counts[key] = observed
        if observed > limit:
            raise _Task4ProofLimit(phase, counter, observed, limit)

    def state_event(self, phase: str) -> None:
        limits = {
            "selector": _TASK4_SELECTOR_STATE_EVENT_CAP,
            "splitter": _TASK4_SPLITTER_STATE_EVENT_CAP,
            "unlink": _TASK4_UNLINK_STATE_EVENT_CAP,
        }
        self._tick(phase, "state-event", limits[phase])

    def expression(self, phase: str) -> None:
        if phase == "selector":
            limit = _TASK4_SELECTOR_EXPRESSION_CAP
        elif phase in {"splitter", "unlink"}:
            limit = _TASK4_HELPER_EXPRESSION_CAP
        else:
            limit = _TASK4_POSTPROCESS_EXPRESSION_CAP
        self._tick(phase, "expression", limit)


class _Task5ProofLimit(RuntimeError):
    """Private fail-closed sentinel for the Task 5 role proof."""

    def __init__(
        self,
        phase: str,
        counter: str,
        observed: int,
        configured: int,
    ) -> None:
        self.phase = phase
        self.counter = counter
        self.observed = observed
        self.configured = configured
        super().__init__(
            f"Task 5 {phase} {counter} cap: "
            f"configured={configured}, observed={observed}"
        )


class _Task5ProofBudget:
    """One phase-labelled finite budget shared by one Task 5 assembly."""

    def __init__(self) -> None:
        self.counts = {
            "state": 0,
            "event": 0,
            "expression": 0,
            "instruction": 0,
            "fixed-point": 0,
        }

    def tick(self, phase: str, counter: str) -> None:
        limits = {
            "state": _TASK5_STATE_CAP,
            "event": _TASK5_EVENT_CAP,
            "expression": _TASK5_EXPRESSION_CAP,
            "instruction": _TASK5_INSTRUCTION_CAP,
            "fixed-point": _TASK5_FIXED_POINT_CAP,
        }
        observed = self.counts[counter] + 1
        self.counts[counter] = observed
        configured = limits[counter]
        if observed > configured:
            raise _Task5ProofLimit(
                phase,
                counter,
                observed,
                configured,
            )


class AnalysisLimitError(CfgRecoveryError):
    """Raised when a deterministic analysis cap reaches its limit."""

    def __init__(self, limit_name: str, configured: int, observed: int) -> None:
        self.limit_name = limit_name
        self.configured = configured
        self.observed = observed
        super().__init__(f"analysis limit reached: {limit_name}, configured={configured}, observed={observed}")


def _freeze_private_stack_memory(
    memory: set[tuple[int, int]] | frozenset[tuple[int, int]],
) -> frozenset[tuple[int, int]]:
    """Reuse immutable taint snapshots and freeze only modified copies."""
    return memory if isinstance(memory, frozenset) else frozenset(memory)


@dataclass(frozen=True, slots=True)
class AnalysisLimits:
    """Explicit structural and fixed-point limits for x86 analysis."""

    max_instructions: int
    max_blocks: int
    max_edges: int
    max_jump_tables: int = 65_536
    max_jump_table_entries: int = 524_288
    max_functions: int = 65_536
    max_finite_targets: int = 65_536
    max_finite_values: int = 8_192
    max_states_per_block: int = 256
    max_contexts_per_entry: int = 256
    max_scc_iterations: int = 65_536
    max_summary_iterations: int = 65_536
    max_fixpoint_updates: int = 8_000_000
    max_exception_entries: int = 65_536
    max_exception_actions: int = 65_536
    max_exception_landing_sites: int = 65_536
    max_producer_domain_passes: int = 65_536
    max_producer_domain_queries: int = 2_000_000
    max_producer_domain_evaluations: int = 500_000
    max_producer_domain_cache_hits: int = 2_000_000
    max_producer_domain_cache_entries: int = 262_144
    max_producer_domain_invalidations: int = 500_000
    max_producer_domain_dependency_rows: int = 65_536

    @classmethod
    def for_image(cls, image: Image) -> AnalysisLimits:
        executable_raw_bytes = sum(
            section.raw_size for section in image.sections if section.is_executable
        )
        return cls(
            max_instructions=executable_raw_bytes,
            max_blocks=executable_raw_bytes,
            max_edges=8 * executable_raw_bytes,
        )

    def check(self, limit_name: str, observed: int) -> None:
        """Fail when ``observed`` reaches the configured high-water cap."""
        if limit_name not in self.__dataclass_fields__:
            raise ValueError(f"unknown analysis limit: {limit_name}")
        configured = getattr(self, limit_name)
        if observed >= configured:
            raise AnalysisLimitError(limit_name, configured, observed)


