def _canonical_json_bytes(value: Any) -> bytes:
    def encode_special(row: Any) -> Any:
        if isinstance(row, set | frozenset):
            return sorted(row)
        if is_dataclass(row):
            return asdict(row)
        raise TypeError(
            f"value is not canonical JSON data: {type(row).__qualname__}"
        )

    return json.dumps(
        value,
        default=encode_special,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")


def _producer_certificate_digest(payload: dict[str, Any]) -> str:
    """Hash a producer certificate without trusting its stored digest."""
    unsigned = dict(payload)
    unsigned.pop("certificate_sha256", None)
    return hashlib.sha256(_canonical_json_bytes(unsigned)).hexdigest()


@dataclass(frozen=True, slots=True)
class AuditAnchor:
    """Closed audit seed bound to exact instruction bytes and their digest."""

    name: str
    address: int
    instruction_bytes: bytes
    evidence: str
    instruction_sha256: str = field(init=False)

    def __post_init__(self) -> None:
        if not self.name:
            raise ValueError("audit anchor name must not be empty")
        if self.address < 0:
            raise ValueError("audit anchor address must not be negative")
        if not isinstance(self.instruction_bytes, bytes):
            raise TypeError("audit anchor instruction_bytes must be bytes")
        if not self.instruction_bytes:
            raise ValueError("audit anchor instruction_bytes must not be empty")
        if not self.evidence:
            raise ValueError("audit anchor evidence must not be empty")
        object.__setattr__(
            self,
            "instruction_sha256",
            hashlib.sha256(self.instruction_bytes).hexdigest(),
        )


