class _PublicationCandidateTrialRejected(CfgRecoveryError):
    def __init__(
        self,
        candidate_identities: tuple[_PublicationCandidateIdentity, ...],
        reason: str,
    ) -> None:
        self.candidate_identities = candidate_identities
        self.reason = reason
        super().__init__(
            "publication candidate trial rejected: "
            f"candidates={len(candidate_identities)};reason={reason}"
        )


def _strict_json_object(raw: bytes, *, path: Path) -> dict[str, Any]:
    def reject_duplicates(pairs):
        value = {}
        for key, item in pairs:
            if key in value:
                raise ProducerCertificateError(
                    f"producer certificate has duplicate key {key!r}: {path}"
                )
            value[key] = item
        return value

    try:
        value = json.loads(raw, object_pairs_hook=reject_duplicates)
    except ProducerCertificateError:
        raise
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ProducerCertificateError(
            f"producer certificate is malformed JSON: {path}"
        ) from exc
    if not isinstance(value, dict):
        raise ProducerCertificateError(
            f"producer certificate root must be an object: {path}"
        )
    return value


class _ProducerCertificateSession:
    """Validate and publish bounded, restart-safe producer proofs."""

    _TOP_LEVEL_KEYS = frozenset(
        {
            "schema",
            "compiler_sha256",
            "query",
            "query_sha256",
            "dependencies",
            "dependency_count",
            "dependency_sha256",
            "limits",
            "high_water_marks",
            "result",
            "certificate_sha256",
        }
    )
    _QUERY_KEYS = frozenset(
        {
            "analysis_semantics",
            "function_entry",
            "movzx_address",
            "movzx_bytes_hex",
            "destination_register",
            "source_base_register",
            "field_path",
            "source_width",
        }
    )
    _LIFECYCLE_QUERY_KEYS = frozenset(
        {
            "analysis_semantics",
            "function_entry",
            "table_base",
            "entry_width",
            "field_path",
            "source_width",
            "consumer_bindings",
        }
    )
    _DEPENDENCY_KEYS = frozenset({"kind", "identifier", "fingerprint"})
    _RESULT_KEYS = frozenset({"status", "values", "provenance"})

    def __init__(
        self,
        *,
        image_sha256: str,
        limits: AnalysisLimits,
        checkpoint_dir: Path,
        query_budget: int,
        progress_callback=None,
    ) -> None:
        if isinstance(query_budget, bool) or not isinstance(query_budget, int) or query_budget < 0:
            raise ValueError("producer_query_budget must be a non-negative int")
        self.image_sha256 = image_sha256
        self.limits = limits
        self.checkpoint_dir = Path(checkpoint_dir)
        self.remaining_budget = query_budget
        self.progress_callback = progress_callback
        self.completed_this_run = 0
        self.validated_query_ids: set[str] = set()
        self.query_states: dict[str, str] = {}
        self.rehydrating_warm_hit = 0
        if self.checkpoint_dir.is_dir():
            self.limits.check(
                "max_producer_domain_cache_entries",
                len(tuple(self.checkpoint_dir.glob("*.json"))),
            )

    def _paths(
        self, query: _MovzxProducerQuery | _ObjectTagLifecycleQuery
    ) -> tuple[Path, ...]:
        return tuple(sorted(self.checkpoint_dir.glob(f"{query.sha256}-*.json")))

    def _path(
        self,
        query: _MovzxProducerQuery | _ObjectTagLifecycleQuery,
        dependency_sha256: str,
    ) -> Path:
        return self.checkpoint_dir / (f"{query.sha256}-{dependency_sha256}.json")

    def _dependency_payload(
        self, dependencies: tuple[tuple[str, int, str], ...]
    ) -> list[dict[str, Any]]:
        return [
            {
                "kind": kind,
                "identifier": identifier,
                "fingerprint": fingerprint,
            }
            for kind, identifier, fingerprint in dependencies
        ]

    def _result_payload(
        self, result: tuple[frozenset[int], str] | None
    ) -> dict[str, Any]:
        if result is None:
            return {
                "status": "blocked",
                "values": [],
                "provenance": "producer-domain-analysis-returned-bottom",
            }
        values, provenance = result
        return {
            "status": "finite",
            "values": sorted(values),
            "provenance": provenance,
        }

    def _certificate_payload(
        self,
        *,
        query: _MovzxProducerQuery | _ObjectTagLifecycleQuery,
        entry: _ProducerDomainMemoEntry,
        recovery: _DirectCfgRecovery,
    ) -> dict[str, Any]:
        dependencies = self._dependency_payload(entry.dependencies)
        payload: dict[str, Any] = {
            "schema": (
                _OBJECT_TAG_LIFECYCLE_CERTIFICATE_SCHEMA
                if isinstance(query, _ObjectTagLifecycleQuery)
                else _PRODUCER_CERTIFICATE_SCHEMA
            ),
            "compiler_sha256": self.image_sha256,
            "query": query.to_dict(),
            "query_sha256": query.sha256,
            "dependencies": dependencies,
            "dependency_count": len(dependencies),
            "dependency_sha256": hashlib.sha256(
                _canonical_json_bytes(dependencies)
            ).hexdigest(),
            "limits": asdict(self.limits),
            "high_water_marks": {
                name: recovery.high_water[name]
                for name in self.limits.__dataclass_fields__
            },
            "result": self._result_payload(entry.result),
        }
        payload["certificate_sha256"] = _producer_certificate_digest(payload)
        return payload

    def _write_atomic(self, path: Path, payload: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        encoded = _canonical_json_bytes(payload) + b"\n"
        temporary_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(
                mode="wb",
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".tmp",
                delete=False,
            ) as temporary:
                temporary_path = Path(temporary.name)
                temporary.write(encoded)
                temporary.flush()
                os.fsync(temporary.fileno())
            os.replace(temporary_path, path)
            temporary_path = None
            directory_fd = os.open(path.parent, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)

    def _require_exact_keys(
        self,
        value: dict[str, Any],
        expected: frozenset[str],
        *,
        label: str,
        path: Path,
    ) -> None:
        if set(value) != expected:
            raise ProducerCertificateError(
                f"producer certificate {label} schema mismatch: {path}"
            )

    def _decode_query(
        self, value: Any, *, path: Path
    ) -> _MovzxProducerQuery | _ObjectTagLifecycleQuery:
        if not isinstance(value, dict):
            raise ProducerCertificateError(
                f"producer certificate query must be an object: {path}"
            )
        semantics = value.get("analysis_semantics")
        if semantics == _OBJECT_TAG_LIFECYCLE_ANALYSIS_SEMANTICS:
            self._require_exact_keys(
                value,
                self._LIFECYCLE_QUERY_KEYS,
                label="query",
                path=path,
            )
            field_path = value["field_path"]
            bindings = value["consumer_bindings"]
            if (
                any(
                    isinstance(value[name], bool)
                    or not isinstance(value[name], int)
                    for name in (
                        "function_entry",
                        "table_base",
                        "entry_width",
                        "source_width",
                    )
                )
                or value["entry_width"] <= 0
                or value["source_width"] != 1
                or field_path != [0]
                or not isinstance(bindings, list)
                or not bindings
            ):
                raise ProducerCertificateError(
                    f"producer certificate lifecycle query is malformed: {path}"
                )
            decoded_bindings = []
            for binding in bindings:
                if (
                    not isinstance(binding, list)
                    or len(binding) != 9
                    or any(
                        isinstance(binding[index], bool)
                        or not isinstance(binding[index], int)
                        for index in (0, 1, 3, 7)
                    )
                    or any(
                        not isinstance(binding[index], str)
                        or not binding[index]
                        for index in (2, 4, 5, 6, 8)
                    )
                ):
                    raise ProducerCertificateError(
                        "producer certificate lifecycle consumer binding is "
                        f"malformed: {path}"
                    )
                decoded_bindings.append(tuple(binding))
            consumer_bindings = tuple(decoded_bindings)
            if consumer_bindings != tuple(sorted(set(consumer_bindings))):
                raise ProducerCertificateError(
                    "producer certificate lifecycle consumer bindings are not "
                    f"canonical: {path}"
                )
            return _ObjectTagLifecycleQuery(
                function_entry=value["function_entry"],
                table_base=value["table_base"],
                entry_width=value["entry_width"],
                field_path=tuple(field_path),
                source_width=value["source_width"],
                consumer_bindings=consumer_bindings,
                analysis_semantics=semantics,
            )
        self._require_exact_keys(value, self._QUERY_KEYS, label="query", path=path)
        field_path = value["field_path"]
        integer_fields = (
            value["function_entry"],
            value["movzx_address"],
            value["source_width"],
        )
        if (
            any(
                isinstance(row, bool) or not isinstance(row, int)
                for row in integer_fields
            )
            or not isinstance(field_path, list)
            or not field_path
            or any(
                isinstance(row, bool) or not isinstance(row, int) for row in field_path
            )
            or not isinstance(value["movzx_bytes_hex"], str)
            or not value["movzx_bytes_hex"]
            or not isinstance(value["destination_register"], str)
            or not value["destination_register"]
            or not isinstance(value["source_base_register"], str)
            or not value["source_base_register"]
        ):
            raise ProducerCertificateError(
                f"producer certificate query is malformed: {path}"
            )
        if (
            not isinstance(semantics, str)
            or semantics != _MOVZX_PRODUCER_ANALYSIS_SEMANTICS
        ):
            raise ProducerCertificateError(
                f"producer certificate analysis semantics mismatch: {path}"
            )
        return _MovzxProducerQuery(
            function_entry=value["function_entry"],
            movzx_address=value["movzx_address"],
            movzx_bytes_hex=value["movzx_bytes_hex"],
            destination_register=value["destination_register"],
            source_base_register=value["source_base_register"],
            field_path=tuple(field_path),
            source_width=value["source_width"],
            analysis_semantics=semantics,
        )

    def _decode_dependencies(
        self,
        value: Any,
        *,
        expected_query: _MovzxProducerQuery | _ObjectTagLifecycleQuery,
        path: Path,
    ) -> tuple[tuple[str, int, str], ...]:
        if not isinstance(value, list):
            raise ProducerCertificateError(
                f"producer certificate dependencies must be a list: {path}"
            )
        rows = []
        for dependency in value:
            if not isinstance(dependency, dict):
                raise ProducerCertificateError(
                    f"producer certificate dependency is malformed: {path}"
                )
            self._require_exact_keys(
                dependency,
                self._DEPENDENCY_KEYS,
                label="dependency",
                path=path,
            )
            kind = dependency["kind"]
            identifier = dependency["identifier"]
            fingerprint = dependency["fingerprint"]
            allowed_kinds = {
                "function",
                "global-slot",
                "dynamic-field",
            }
            if (
                isinstance(expected_query, _ObjectTagLifecycleQuery)
                and expected_query.analysis_semantics
                == _OBJECT_TAG_LIFECYCLE_ANALYSIS_SEMANTICS
            ):
                allowed_kinds.add("absolute-reference")
            if (
                kind not in allowed_kinds
                or isinstance(identifier, bool)
                or not isinstance(identifier, int)
                or not isinstance(fingerprint, str)
                or not re.fullmatch(r"[0-9a-f]{64}", fingerprint)
            ):
                raise ProducerCertificateError(
                    f"producer certificate dependency is malformed: {path}"
                )
            rows.append((kind, identifier, fingerprint))
        if rows != sorted(set(rows)):
            raise ProducerCertificateError(
                f"producer certificate dependencies are not canonical: {path}"
            )
        if not any(
            kind == "function"
            and identifier == expected_query.function_entry
            for kind, identifier, _fingerprint in rows
        ):
            raise ProducerCertificateError(
                f"producer certificate is missing its root dependency: {path}"
            )
        return tuple(rows)

    def _decode_result(
        self, value: Any, *, path: Path
    ) -> tuple[frozenset[int], str] | None:
        if not isinstance(value, dict):
            raise ProducerCertificateError(
                f"producer certificate result must be an object: {path}"
            )
        self._require_exact_keys(value, self._RESULT_KEYS, label="result", path=path)
        status = value["status"]
        values = value["values"]
        provenance = value["provenance"]
        if (
            status not in {"finite", "blocked"}
            or not isinstance(values, list)
            or any(
                isinstance(row, bool)
                or not isinstance(row, int)
                or not 0 <= row <= 0xFF
                for row in values
            )
            or values != sorted(set(values))
            or not isinstance(provenance, str)
            or not provenance
            or (status == "finite" and not values)
            or (status == "blocked" and values)
        ):
            raise ProducerCertificateError(
                f"producer certificate result is malformed: {path}"
            )
        if status == "blocked":
            return None
        return frozenset(values), provenance

    def _load(
        self,
        *,
        path: Path,
        expected_query: _MovzxProducerQuery | _ObjectTagLifecycleQuery,
        recovery: _DirectCfgRecovery,
    ) -> _ProducerDomainMemoEntry | None:
        payload = _strict_json_object(path.read_bytes(), path=path)
        self._require_exact_keys(payload, self._TOP_LEVEL_KEYS, label="root", path=path)
        stored_digest = payload["certificate_sha256"]
        if not isinstance(
            stored_digest, str
        ) or stored_digest != _producer_certificate_digest(payload):
            raise ProducerCertificateError(
                f"producer certificate digest mismatch: {path}"
            )
        expected_schema = (
            _OBJECT_TAG_LIFECYCLE_CERTIFICATE_SCHEMA
            if isinstance(expected_query, _ObjectTagLifecycleQuery)
            else _PRODUCER_CERTIFICATE_SCHEMA
        )
        if payload["schema"] != expected_schema:
            raise ProducerCertificateError(
                f"producer certificate schema mismatch: {path}"
            )
        if payload["compiler_sha256"] != self.image_sha256:
            raise ProducerCertificateError(
                f"producer certificate compiler SHA mismatch: {path}"
            )
        query = self._decode_query(payload["query"], path=path)
        if query != expected_query or payload["query_sha256"] != query.sha256:
            raise ProducerCertificateError(
                f"producer certificate semantic query mismatch: {path}"
            )
        if payload["limits"] != asdict(self.limits):
            raise ProducerCertificateError(
                f"producer certificate analysis limits mismatch: {path}"
            )
        high_water = payload["high_water_marks"]
        if (
            not isinstance(high_water, dict)
            or set(high_water) != set(self.limits.__dataclass_fields__)
            or any(
                isinstance(value, bool)
                or not isinstance(value, int)
                or value < 0
                or value >= getattr(self.limits, name)
                for name, value in high_water.items()
            )
        ):
            raise ProducerCertificateError(
                f"producer certificate high-water marks are malformed: {path}"
            )
        dependencies = self._decode_dependencies(
            payload["dependencies"],
            expected_query=query,
            path=path,
        )
        dependency_payload = self._dependency_payload(dependencies)
        if (
            payload["dependency_count"] != len(dependencies)
            or payload["dependency_sha256"]
            != hashlib.sha256(_canonical_json_bytes(dependency_payload)).hexdigest()
        ):
            raise ProducerCertificateError(
                f"producer certificate dependency fingerprint mismatch: {path}"
            )
        expected_path = self._path(query, payload["dependency_sha256"])
        if path != expected_path:
            raise ProducerCertificateError(
                f"producer certificate path binding mismatch: {path}"
            )
        result = self._decode_result(payload["result"], path=path)
        current = tuple(
            (
                kind,
                identifier,
                recovery._producer_dependency_fingerprint(kind, identifier),
            )
            for kind, identifier, _fingerprint in dependencies
        )
        if current != dependencies:
            return None
        return _ProducerDomainMemoEntry(
            image_sha256=self.image_sha256,
            dependencies=dependencies,
            result=result,
        )

    def evaluate(
        self,
        *,
        recovery: _DirectCfgRecovery,
        query: _MovzxProducerQuery | _ObjectTagLifecycleQuery,
        compute,
    ) -> tuple[frozenset[int], str] | None:
        query_id = query.sha256
        recovery.producer_query_ids.add(query_id)
        paths = self._paths(query)

        def clear_lifecycle_dependency_caches() -> None:
            recovery.field_preservation_cache.clear()
            recovery.relative_pointer_state_cache.clear()
            recovery.argument_return_offset_cache.clear()

        for path in paths:
            entry = self._load(path=path, expected_query=query, recovery=recovery)
            if entry is not None:
                if isinstance(query, _ObjectTagLifecycleQuery):
                    # Lifecycle checkpoints retain only the aggregate domain
                    # and dependency rows.  Re-run the normal computation on
                    # every warm hit so recovery-local publication witnesses
                    # and tentative-hypothesis evidence are reconstructed.
                    # This rehydration consumes no query budget and must match
                    # the exact validated dependency-bound result.
                    recovery_state = (
                        dict(recovery.producer_domain_memo),
                        dict(recovery.field_preservation_cache),
                        dict(
                            recovery.return_path_publication_certificate_memo
                        ),
                        dict(recovery.allocator_totality_cache),
                        dict(recovery.publication_reference_inventory_cache),
                        set(recovery.publication_table_hypotheses),
                        dict(recovery.publication_guard_candidates),
                        dict(
                            recovery.provisional_publication_guard_domains
                        ),
                        set(recovery.producer_query_ids),
                        dict(recovery.producer_progress),
                        dict(recovery.high_water),
                        dict(recovery.relative_pointer_state_cache),
                        dict(recovery.argument_return_offset_cache),
                    )
                    session_state = (
                        set(self.validated_query_ids),
                        dict(self.query_states),
                        self.remaining_budget,
                        self.completed_this_run,
                    )

                    def rollback_rehydration() -> None:
                        mappings = (
                            (
                                recovery.producer_domain_memo,
                                recovery_state[0],
                            ),
                            (
                                recovery.field_preservation_cache,
                                recovery_state[1],
                            ),
                            (
                                recovery.return_path_publication_certificate_memo,
                                recovery_state[2],
                            ),
                            (
                                recovery.allocator_totality_cache,
                                recovery_state[3],
                            ),
                            (
                                recovery.publication_reference_inventory_cache,
                                recovery_state[4],
                            ),
                            (
                                recovery.publication_guard_candidates,
                                recovery_state[6],
                            ),
                            (
                                recovery.provisional_publication_guard_domains,
                                recovery_state[7],
                            ),
                            (
                                recovery.producer_progress,
                                recovery_state[9],
                            ),
                            (
                                recovery.high_water,
                                recovery_state[10],
                            ),
                            (
                                recovery.relative_pointer_state_cache,
                                recovery_state[11],
                            ),
                            (
                                recovery.argument_return_offset_cache,
                                recovery_state[12],
                            ),
                        )
                        for current, prior in mappings:
                            current.clear()
                            current.update(prior)
                        recovery.publication_table_hypotheses.clear()
                        recovery.publication_table_hypotheses.update(
                            recovery_state[5]
                        )
                        recovery.producer_query_ids.clear()
                        recovery.producer_query_ids.update(
                            recovery_state[8]
                        )
                        self.validated_query_ids.clear()
                        self.validated_query_ids.update(session_state[0])
                        self.query_states.clear()
                        self.query_states.update(session_state[1])
                        self.remaining_budget = session_state[2]
                        self.completed_this_run = session_state[3]

                    recovery.producer_domain_memo.pop(query.memo_key, None)
                    clear_lifecycle_dependency_caches()
                    self.rehydrating_warm_hit += 1
                    try:
                        result = recovery._producer_domain_cached(
                            query.memo_key, query.function_entry, compute
                        )
                    except BaseException:
                        rollback_rehydration()
                        raise
                    finally:
                        self.rehydrating_warm_hit -= 1
                    rehydrated = recovery.producer_domain_memo.get(
                        query.memo_key
                    )
                    if (
                        rehydrated is None
                        or rehydrated.result != entry.result
                        or rehydrated.dependencies != entry.dependencies
                        or self.remaining_budget != session_state[2]
                        or self.completed_this_run != session_state[3]
                    ):
                        rollback_rehydration()
                        continue
                    # A blocked lifecycle aggregate can be a provisional
                    # publication screen rather than semantic bottom.  Its
                    # successful in-process rehydration is the authority for
                    # the current tentative witness; the durable blocked row
                    # only proves that its own dependency variant is current.
                    # Definitive finite publication replay still requires
                    # exact dependency equality above.
                else:
                    recovery.producer_domain_memo[query.memo_key] = entry
                    result = recovery._producer_domain_cached(
                        query.memo_key, query.function_entry, compute
                    )
                self.validated_query_ids.add(query_id)
                self.query_states[query_id] = "validated"
                if self.progress_callback is not None:
                    self.progress_callback(f"producer query validated: query={query_id};movzx={query.movzx_address:#x}")
                return result
        if paths:
            self.validated_query_ids.discard(query_id)
            self.query_states[query_id] = "stale"

        if self.remaining_budget == 0 or self.rehydrating_warm_hit:
            recovery._producer_progress_increment("max_producer_domain_queries")
            self.query_states[query_id] = "pending"
            return None

        recovery.producer_domain_memo.pop(query.memo_key, None)
        if isinstance(query, _ObjectTagLifecycleQuery):
            clear_lifecycle_dependency_caches()
        self.remaining_budget -= 1
        if self.progress_callback is not None:
            self.progress_callback(
                "producer query evaluating: "
                f"query={query_id};movzx={query.movzx_address:#x};"
                f"remaining_budget={self.remaining_budget}"
            )
        result = recovery._producer_domain_cached(
            query.memo_key, query.function_entry, compute
        )
        entry = recovery.producer_domain_memo.get(query.memo_key)
        if entry is None:
            raise CfgRecoveryError(
                "producer-domain evaluation did not publish its memo entry"
            )
        payload = self._certificate_payload(query=query, entry=entry, recovery=recovery)
        path = self._path(query, payload["dependency_sha256"])
        self._write_atomic(path, payload)
        self.completed_this_run += 1
        self.validated_query_ids.discard(query_id)
        self.query_states[query_id] = "completed"
        if self.progress_callback is not None:
            self.progress_callback(
                "producer query checkpointed: "
                f"query={query_id};movzx={query.movzx_address:#x};"
                f"status={payload['result']['status']};path={path}"
            )
        return result

    def require_fresh_resume(self, final_query_ids: set[str]) -> None:
        pending = sum(
            self.query_states.get(query_id) == "pending" for query_id in final_query_ids
        )
        if self.completed_this_run or pending:
            raise ProducerCheckpointIncomplete(
                completed_this_run=self.completed_this_run,
                discovered_queries=len(final_query_ids),
                validated_queries=len(final_query_ids & self.validated_query_ids),
                pending_queries=pending,
                checkpoint_dir=self.checkpoint_dir,
            )


class _RelocatedRejectionLedger:
    """Durably skip only an exactly reproduced rejected relocated batch."""

    def __init__(self, checkpoint_dir: Path, progress_callback=None) -> None:
        self.directory = Path(checkpoint_dir) / ".relocated-rejection-ledger-v1"
        self.progress_callback = progress_callback

    def _report(self, state: str, digest: str) -> None:
        if self.progress_callback is not None:
            self.progress_callback(
                f"hypothesis replay rejection-ledger-{state}: batch={digest}"
            )

    def _path(self, digest: str) -> Path:
        return self.directory / f"{digest}.json"

    def contains(
        self, contract: dict[str, Any], batch: list[dict[str, Any]]
    ) -> dict[str, int] | None:
        payload = json.loads(
            _canonical_json_bytes(
                {
                    "schema": _RELOCATED_REJECTION_LEDGER_SCHEMA,
                    "contract": contract,
                    "batch": batch,
                }
            )
        )
        digest = hashlib.sha256(_canonical_json_bytes(payload)).hexdigest()
        path = self._path(digest)
        if not path.exists():
            self._report("miss", digest)
            return None
        try:
            value = _strict_json_object(path.read_bytes(), path=path)
            if set(value) != {
                "schema", "contract", "batch", "high_water_marks", "sha256"
            }:
                raise ProducerCertificateError("rejection ledger schema mismatch")
            unsigned = {key: value[key] for key in ("schema", "contract", "batch", "high_water_marks")}
            if (
                value["schema"] != _RELOCATED_REJECTION_LEDGER_SCHEMA
                or not isinstance(value["sha256"], str)
                or hashlib.sha256(_canonical_json_bytes(unsigned)).hexdigest() != value["sha256"]
                or {key: unsigned[key] for key in ("schema", "contract", "batch")} != payload
                or not isinstance(value["high_water_marks"], dict)
                or set(value["high_water_marks"])
                != set(contract["limits"])
                or any(
                    isinstance(row, bool)
                    or not isinstance(row, int)
                    or row < 0
                    or row >= contract["limits"][name]
                    for name, row in value["high_water_marks"].items()
                )
            ):
                raise ProducerCertificateError("rejection ledger binding mismatch")
        except (OSError, ProducerCertificateError, ValueError):
            self._report("invalid", digest)
            return None
        self._report("hit", digest)
        return value["high_water_marks"]

    def publish(
        self, contract: dict[str, Any], batch: list[dict[str, Any]], cfg: RawCfg
    ) -> None:
        payload = json.loads(
            _canonical_json_bytes(
                {
                    "schema": _RELOCATED_REJECTION_LEDGER_SCHEMA,
                    "contract": contract,
                    "batch": batch,
                }
            )
        )
        digest = hashlib.sha256(_canonical_json_bytes(payload)).hexdigest()
        path = self._path(digest)
        value = {
            **payload,
            "high_water_marks": {
                row.limit_name: row.observed for row in cfg.high_water_marks
            },
        }
        value["sha256"] = hashlib.sha256(_canonical_json_bytes(value)).hexdigest()
        directory_existed = self.directory.exists()
        self.directory.mkdir(parents=True, exist_ok=True)
        if not directory_existed:
            parent_fd = os.open(self.directory.parent, os.O_RDONLY)
            try:
                os.fsync(parent_fd)
            finally:
                os.close(parent_fd)
        temporary_path: Path | None = None
        try:
            with tempfile.NamedTemporaryFile(mode="wb", dir=self.directory, prefix=f".{digest}.", suffix=".tmp", delete=False) as temporary:
                temporary_path = Path(temporary.name)
                temporary.write(_canonical_json_bytes(value) + b"\n")
                temporary.flush()
                os.fsync(temporary.fileno())
            os.replace(temporary_path, path)
            temporary_path = None
            directory_fd = os.open(self.directory, os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
        finally:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)
        self._report("write", digest)


@dataclass(frozen=True, slots=True)
class _ObjectCallbackConsumer:
    transfer_address: int
    slot_offset: int
    target: int
    receiver_argument_index: int | None


@dataclass(frozen=True, slots=True)
class _ObjectCallbackTableHypothesis:
    table_base: int
    store_address: int
    object_field: int
    receiver_identity: _AbstractObjectIdentity | None
    consumers: tuple[_ObjectCallbackConsumer, ...]
    records: tuple[SeedRecord, ...]
    data_evidence: _DataEvidence


@dataclass(frozen=True, slots=True)
class _CopiedDescriptorCallbackHypothesis:
    source_bases: tuple[int, ...]
    target_source_bases: tuple[tuple[int, tuple[int, ...]], ...]
    records: tuple[SeedRecord, ...]
    data_evidence: tuple[_DataEvidence, ...]


@dataclass(frozen=True, slots=True)
class _RelocatedDispatchSlotHypothesis:
    transfer_address: int
    table_base: int
    index: int
    slot_address: int
    target: int
    records: tuple[SeedRecord, ...]


@dataclass(frozen=True, slots=True)
class _ClosedObjectOrigin:
    has_target_constructor: bool
    rejected_tags: frozenset[int]
    detail: str


@dataclass(frozen=True, slots=True)
class _RegisterSlice:
    family: str
    mask: int
    name: str


@dataclass(frozen=True, slots=True)
class _ValueDependency:
    kind: str
    register: _RegisterSlice | None = None
    value: int | None = None
    operand_index: int | None = None


@dataclass(frozen=True, slots=True)
class _RegisterEffect:
    destination: _RegisterSlice
    dependencies: tuple[_ValueDependency, ...]
    taint_mask: int | None = None


@dataclass(frozen=True, slots=True)
class _X87State:
    """Finite physical x87/MMX payload, TOP, and tag abstraction."""

    phys_taint: tuple[int, int, int, int, int, int, int, int]
    top_mask: int
    valid_must: int
    valid_may: int

    def __post_init__(self) -> None:
        if len(self.phys_taint) != 8:
            raise ValueError("x87 physical state must contain eight slots")
        if not 0 < self.top_mask <= 0xFF:
            raise ValueError("x87 TOP mask must contain one to eight values")
        if self.valid_must & ~self.valid_may:
            raise ValueError("x87 must-valid tags exceed may-valid tags")
        if (self.valid_must | self.valid_may) & ~0xFF:
            raise ValueError("x87 tag masks exceed eight physical slots")
        if any(mask < 0 or mask >> 80 for mask in self.phys_taint):
            raise ValueError("x87 physical taint exceeds 80-bit payload")

    @classmethod
    def clean_unknown(cls) -> _X87State:
        return cls((0,) * 8, 0xFF, 0, 0xFF)


@dataclass(slots=True)
class _TaintState:
    registers: dict[str, int]
    x87: _X87State

    @classmethod
    def empty(cls) -> _TaintState:
        return cls({}, _X87State((0,) * 8, 1, 0, 0xFF))


@dataclass(frozen=True, slots=True)
class _X87Effect:
    kind: str
    target: int = 0
    pop_count: int = 0
    dependencies: tuple[_ValueDependency, ...] = ()


@dataclass(frozen=True, slots=True)
class MemoryWriteSpec:
    """One audited memory sink and the values actually stored by it."""

    classification: str
    dependencies: tuple[_ValueDependency, ...]


@dataclass(frozen=True, slots=True)
class _InstructionValueFlow:
    register_effects: tuple[_RegisterEffect, ...] = ()
    memory_writes: tuple[MemoryWriteSpec, ...] = ()
    join_overlapping_register_effects: bool = False
    taint_blocker_dependencies: tuple[_ValueDependency, ...] = ()
    taint_blocker_reason: str | None = None
    x87_effect: _X87Effect | None = None


