def _validate_capstone_audit_contract() -> None:
    enum_rows = sorted(
        (name, value)
        for name, value in vars(x86_const).items()
        if name.startswith("X86_INS_") and isinstance(value, int)
    )
    enum_digest = hashlib.sha256(
        "\n".join(f"{name}={value}" for name, value in enum_rows).encode()
    ).hexdigest()
    observed = (
        capstone.__version__,
        x86_const.X86_INS_ENDING,
        len(enum_rows),
        enum_digest,
    )
    expected = (
        _AUDITED_CAPSTONE_VERSION,
        _AUDITED_X86_INS_ENDING,
        _AUDITED_X86_ENUM_COUNT,
        _AUDITED_X86_ENUM_SHA256,
    )
    if observed != expected:
        raise CfgRecoveryError(
            "Capstone audit contract mismatch: "
            f"observed-version={observed[0]};"
            f"observed-ending={observed[1]};"
            f"observed-enum-count={observed[2]};"
            f"observed-enum-sha256={observed[3]};"
            f"expected-version={expected[0]};"
            f"expected-ending={expected[1]};"
            f"expected-enum-count={expected[2]};"
            f"expected-enum-sha256={expected[3]}"
        )


class _DirectCfgRecovery:
    """Address-priority direct decoder with exact instruction ownership."""

    def __init__(
        self,
        image: Image,
        seed_inventory: SeedInventory,
        limits: AnalysisLimits,
        rejected_object_callback_tables: frozenset[int] = frozenset(),
        accepted_object_callback_hypotheses: tuple[_ObjectCallbackTableHypothesis, ...] = (),
        accepted_publication_table_hypotheses: tuple[
            _PublicationTableHypothesis, ...
        ] = (),
        producer_domain_memo: dict[tuple[Any, ...], _ProducerDomainMemoEntry] | None = None,
        producer_certificate_session: _ProducerCertificateSession | None = None,
        finite_control_memo: dict[tuple[Any, ...], _ProducerDomainMemoEntry] | None = None,
        readable_global_effect_store: (
            ReadableGlobalEffectMemoStore | None
        ) = None,
        decoded_instruction_cache_limit: int | None = None,
    ) -> None:
        _validate_capstone_audit_contract()
        if decoded_instruction_cache_limit is None:
            decoded_instruction_cache_limit = (
                _DECODED_INSTRUCTION_CACHE_LIMIT
            )
        if (
            isinstance(decoded_instruction_cache_limit, bool)
            or not isinstance(
                decoded_instruction_cache_limit,
                int,
            )
            or decoded_instruction_cache_limit <= 0
        ):
            raise ValueError(
                "decoded_instruction_cache_limit must be a "
                "positive int"
            )
        self.image = image
        self.limits = limits
        self.decoded_instruction_cache_limit = (
            decoded_instruction_cache_limit
        )
        self.highlow_relocation_vas = frozenset(
            relocation.va for relocation in image.relocations if relocation.type == 3
        )
        relocation_types_by_va: dict[int, list[int]] = {}
        for relocation in image.relocations:
            relocation_types_by_va.setdefault(relocation.va, []).append(
                relocation.type
            )
        self.relocation_types_by_va = {
            address: tuple(types)
            for address, types in relocation_types_by_va.items()
        }
        self.highlow_relocation_references_by_value: (
            dict[int, frozenset[int]] | None
        ) = None
        self.absolute_memory_write_fingerprint_index_version: int | None = None
